import{_ as p,W as d,s as i,u as l,ah as u,I as e,w as t,Z as o,A as a}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const x=JSON.parse('{"title":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220518 How To Reset Sudo Password In Ubuntu 22.04 - 20.04 LTS","title":"如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码","tag":"202205"},"relativePath":"202205/20220518 How To Reset Sudo Password In Ubuntu 22.04 - 20.04 LTS.md","filePath":"[post].md"}'),r={name:"202205/20220518 How To Reset Sudo Password In Ubuntu 22.04 - 20.04 LTS.md"};function b(c,s,h,m,g,T){const n=d("Link");return l(),i("div",null,[s[21]||(s[21]=u('<h1 id="如何在-ubuntu-22-04-20-04-lts-中重新设置-sudo-密码" tabindex="-1">如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码 <a class="header-anchor" href="#如何在-ubuntu-22-04-20-04-lts-中重新设置-sudo-密码" aria-label="Permalink to 如何在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/29/083429wzrvirffinihrfv5.jpg" alt=""></p><blockquote><p>在 Ubuntu 中重新设置已忘记的 root 用户的密码</p></blockquote><p>这篇简单的指南将向你解释，如何在 Ubuntu 22.04 好 20.04 LTS 桌面环境中，以及从服务器版本中的 <ruby>恢复<rt>rescue</rt></ruby> 模式中重新设置 sudo 密码。</p><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to 介绍">​</a></h3>',5)),e("p",null,[s[1]||(s[1]=t("在 ")),o(n,{href:"https://ostechnix.com/install-ubuntu-desktop/"},{default:a(()=>s[0]||(s[0]=[t("安装 Ubuntu")])),_:1}),s[2]||(s[2]=t(" 时，创建的一个新用户将会带有 ")),s[3]||(s[3]=e("code",null,"sudo",-1)),s[4]||(s[4]=t(" 权限，用以执行各种各样的管理任务。"))]),s[22]||(s[22]=u('<p>如果你的 Ubuntu 系统有多个 <code>sudo</code> 用户，你能够从另外一个 <code>sudo</code> 用户的账号下，轻松地重新设置所忘记的一个 <code>sudo</code> 用户或管理员用户的密码。</p><p>如果你只有一个 <code>sudo</code> 用户，并且忘记了密码怎么办？没有问题! 从 Ubuntu 的 <ruby>恢复<rt>rescue</rt></ruby> 或 <ruby>单一用户<rt>single user</rt></ruby> 模式中恢复 <code>sudo</code> 用户密码很容易。</p><p>虽然这篇指南是在 Ubuntu 22.04 和 20.04 LTS 版本上进行的正式测试，不过，下面给定的步骤对于其它的 Ubuntu 版本和衍生版本来说是相同的。</p><h3 id="在-ubuntu-22-04-20-04-lts-中重新设置-sudo-密码" tabindex="-1">在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-lts-中重新设置-sudo-密码" aria-label="Permalink to 在 Ubuntu 22.04 / 20.04 LTS 中重新设置 sudo 密码">​</a></h3><p>首先，启动你的 Ubuntu 系统到 <ruby>恢复<rt>rescue</rt></ruby> 模式下，来重新设置一个 <code>sudo</code> 用户的密码，操作如下面的链接所述。</p>',5)),e("blockquote",null,[e("p",null,[o(n,{href:"https://ostechnix.com/how-to-boot-into-rescue-mode-or-emergency-mode-in-ubuntu-18-04/"},{default:a(()=>s[5]||(s[5]=[t("如何启动到 Ubuntu 22.04 /  20.04 / 18.04 的 "),e("ruby",null,[t("恢复"),e("rt",null,"rescue")],-1),t(" 模式 或 "),e("ruby",null,[t("急救"),e("rt",null,"Emergency")],-1),t("模式 ")])),_:1})])]),s[23]||(s[23]=u(`<p>现在，进入到 <ruby>恢复<rt>rescue</rt></ruby> 模式下，通过运行下面的命令，以读/写的模式挂载根（<code>/</code>）文件系统：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mount -n -o remount,rw /</span></span></code></pre></div><p>现在，使用 <code>passwd</code> 命令来重新设置 <code>sudo</code> 用户的密码:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># passwd ostechnix</span></span></code></pre></div><p>在这里，<code>ostechnix</code> 是 sudo 用户的名称。使用你自己的用户名称来替换掉它。</p><p>输入两次密码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: password updated successfully</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Reset-Sudo-Password-In-Ubuntu.png" alt="Reset Sudo Password In Ubuntu 22.04 / 20.04 LTS"></p><p>就这样。我们已经重新设置 <code>sudo</code> 用户密码。如果你按照上面链接所述的方法 1 进入到 <ruby>恢复<rt>rescue</rt></ruby> 模式，按下 <code>Ctrl+d</code> 组合键来启动到正常模式。或者，你也可以输入下面的任意一个命令来启动到正常模式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># systemctl default</span></span></code></pre></div><p>或，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># exit</span></span></code></pre></div><p>如果你想重新启动系统，而不是启动到正常模式，输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># systemctl reboot</span></span></code></pre></div><p>如果你已经按照上面链接所述的方法 2 进入到<ruby>恢复<rt>rescue</rt></ruby> 模式，输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># exit</span></span></code></pre></div><p>你将返回到 <ruby>恢复菜单<rt>recovery menu</rt></ruby>。现在选择 “<ruby>恢复正常启动<rt>Resume normal boot</rt></ruby>”，并按下回车键。</p><p><img src="https://ostechnix.com/wp-content/uploads/2020/05/Boot-into-normal-mode-in-Ubuntu.png" alt="Boot Into Normal Mode In Ubuntu"></p><p>在强调一次，选择 “<ruby>确定<rt>OK</rt></ruby>” 按钮，并按下回车按键来继续启动到正常模式：</p><p><img src="https://ostechnix.com/wp-content/uploads/2020/05/Booting-into-normal-mode-from-rescue-mode-in-Ubuntu.png" alt="Exit Recovery Mode And Boot Into Normal Mode"></p><p>现在，你在运行管理命令时可以使用新的 <code>sudo</code> 密码。</p><h3 id="如果我把用户名称和密码都忘了怎么办" tabindex="-1">如果我把用户名称和密码都忘了怎么办？ <a class="header-anchor" href="#如果我把用户名称和密码都忘了怎么办" aria-label="Permalink to 如果我把用户名称和密码都忘了怎么办？">​</a></h3><p>如果你忘记了用户名称，在 <ruby>恢复<rt>rescue</rt></ruby> 模式下，你可以很容易地列出你的 Linux 系统中的用户名称，使用目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cat etc/passwd</span></span></code></pre></div><p>来自我 Ubuntu 22.04 系统的输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>ostechnix:x:1000:1000:Ostechnix,,,:/home/ostechnix:/bin/bash</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>好了，现在，你找到用户名称了。只需要按照上面的步骤来重新设置用户的密码即可。</p><hr>`,28)),e("p",null,[s[7]||(s[7]=t("via: ")),o(n,{href:"https://ostechnix.com/how-to-reset-sudo-password-in-ubuntu-20-04-lts/"},{default:a(()=>s[6]||(s[6]=[t("https://ostechnix.com/how-to-reset-sudo-password-in-ubuntu-20-04-lts/")])),_:1})]),e("p",null,[s[12]||(s[12]=t("作者：")),o(n,{href:"https://ostechnix.com/author/sk/"},{default:a(()=>s[8]||(s[8]=[t("sk")])),_:1}),s[13]||(s[13]=t(" 选题：")),o(n,{href:"https://github.com/lkxed"},{default:a(()=>s[9]||(s[9]=[t("lkxed")])),_:1}),s[14]||(s[14]=t(" 译者：")),o(n,{href:"https://github.com/robsean"},{default:a(()=>s[10]||(s[10]=[t("robsean")])),_:1}),s[15]||(s[15]=t(" 校对：")),o(n,{href:"https://github.com/wxy"},{default:a(()=>s[11]||(s[11]=[t("wxy")])),_:1})]),e("p",null,[s[18]||(s[18]=t("本文由 ")),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>s[16]||(s[16]=[t("LCTT")])),_:1}),s[19]||(s[19]=t(" 原创编译，")),o(n,{href:"https://linux.cn/"},{default:a(()=>s[17]||(s[17]=[t("Linux中国")])),_:1}),s[20]||(s[20]=t(" 荣誉推出"))])])}const k=p(r,[["render",b]]);export{x as __pageData,k as default};
